var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var n := 0
var ok := true
for b in H.phase().dice_log:
	if typeof(b) == TYPE_DICTIONARY and str(b.get("context", "")) == "ork11e_fight_on_death":
		n += 1
		if bool(b.get("kept", false)) != (int(b.rolls_raw[0]) + int(b.modifier) >= 3):
			ok = false
print("[cus11e duty] fight-on-death rolls: ", n)
return n >= 1 and ok
